import * as React from "react";

export type TvStaticIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function TvStaticIcon({ size = 20, ...props }: TvStaticIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3.5" y="5.5" width="17" height="12" rx="1.5" /><path d="M7 9.5h2M11 9.5h1M14 12h3M8 13.5h3" />
    </svg>
  );
}
